package th.co.maeyai.onpos;
import android.app.*;import android.os.*;import android.content.*;import android.net.Uri;import android.database.*;import android.database.sqlite.*;import android.view.*;import android.widget.*;import java.text.*;import java.util.*;
public class MainActivity extends Activity {
 PosDatabase helper; LinearLayout root,body; NumberFormat nf=NumberFormat.getNumberInstance(new Locale("th","TH"));
 public void onCreate(Bundle b){super.onCreate(b);helper=PosDatabase.get(this);getWindow().setStatusBarColor(0xff173b32);home();}
 TextView label(String s,int z){TextView t=new TextView(this);t.setText(s);t.setTextSize(z);t.setPadding(12,10,12,10);return t;}
 void page(String title){root=new LinearLayout(this);root.setOrientation(1);root.setPadding(14,10,14,10);root.setBackgroundColor(0xfff3f6f3);setContentView(root);root.addView(label(title,24));ScrollView sc=new ScrollView(this);body=new LinearLayout(this);body.setOrientation(1);sc.addView(body);root.addView(sc,new LinearLayout.LayoutParams(-1,0,1));Button back=new Button(this);back.setText("ย้อนกลับ");back.setOnClickListener(v->home());root.addView(back);}
 void button(String s,Runnable r){Button b=new Button(this);b.setText(s);b.setAllCaps(false);b.setOnClickListener(v->r.run());body.addView(b);}
 EditText input(String h){EditText e=new EditText(this);e.setSingleLine(true);e.setHint(h);body.addView(e);return e;}
 void home(){page("ร้านแม่ใหญ่อ่อน POS");button("1 ขายสินค้า",this::sell);button("2 คลังสินค้า",this::inventory);button("3 สร้างบาร์โค้ด",this::barcode);button("4 ประวัติการขาย",this::history);button("5 บัญชีเชื่อ / ชำระหนี้",this::debts);button("6 รายงาน",this::reports);button("ตั้งค่า / ตรวจฐานข้อมูล",this::settings);}
 void addProduct(){page("เพิ่มสินค้า");EditText n=input("ชื่อสินค้า"),p=input("ราคาขาย (บาท)"),c=input("ต้นทุน (บาท)"),q=input("จำนวนเริ่มต้น"),l=input("ลิมิตสต๊อก");button("บันทึกสินค้า",()->{try{String name=n.getText().toString().trim();long price=Long.parseLong(p.getText().toString())*100,cost=Long.parseLong(c.getText().toString())*100;int qty=Integer.parseInt(q.getText().toString()),limit=l.length()==0?0:Integer.parseInt(l.getText().toString());if(name.isEmpty()||price<0||cost<0||qty<0||limit<0)throw new Exception();SQLiteDatabase d=helper.getWritableDatabase();d.beginTransaction();try{String id=PosDatabase.id(),now=PosDatabase.now();ContentValues v=new ContentValues();v.put("id",id);v.put("name",name);v.put("price_sat",price);v.put("cost_sat",cost);v.put("stock",qty);v.put("low_limit",limit);v.put("created_at",now);v.put("updated_at",now);d.insertOrThrow("products",null,v);if(qty>0)ledger(d,id,qty,0,qty,"opening",id,now);audit(d,"product",id,"created",name,now);d.setTransactionSuccessful();}finally{d.endTransaction();}inventory();}catch(Exception x){err("ข้อมูลสินค้าไม่ถูกต้อง");}});}
 void inventory(){page("คลังสินค้า");button("เพิ่มสินค้า",this::addProduct);try(Cursor c=helper.getReadableDatabase().rawQuery("SELECT id,name,barcode,price_sat,stock,low_limit FROM products WHERE active=1 ORDER BY name COLLATE NOCASE",null)){while(c.moveToNext()){String id=c.getString(0),name=c.getString(1),bc=c.getString(2);int stock=c.getInt(4),lim=c.getInt(5);long price=c.getLong(3);button(name+" | "+nf.format(price/100.0)+" บาท | คงเหลือ "+stock+(stock<=lim?" (ถึงลิมิต)":""),()->product(id,name,bc,stock,price));}}}
 void product(String id,String name,String bc,int stock,long old){new AlertDialog.Builder(this).setTitle(name).setItems(new String[]{"แก้ราคา","ตรวจนับสต๊อก","ดูบาร์โค้ด"},(d,w)->{if(w==0)price(id,old);else if(w==1)count(id,stock);else info("บาร์โค้ด: "+(bc==null?"ยังไม่มี":bc));}).show();}
 void price(String id,long old){EditText e=new EditText(this);e.setHint("ราคาใหม่ (บาท)");e.setInputType(2);new AlertDialog.Builder(this).setTitle("แก้ราคา").setView(e).setPositiveButton("บันทึก",(d,w)->{try{long v=Long.parseLong(e.getText().toString())*100;SQLiteDatabase db=helper.getWritableDatabase();db.beginTransaction();try{ContentValues c=new ContentValues();c.put("price_sat",v);c.put("updated_at",PosDatabase.now());db.update("products",c,"id=?",new String[]{id});ContentValues h=new ContentValues();h.put("id",PosDatabase.id());h.put("product_id",id);h.put("old_price_sat",old);h.put("new_price_sat",v);h.put("changed_at",PosDatabase.now());db.insertOrThrow("price_history",null,h);audit(db,"product",id,"price_changed",old+"->"+v,PosDatabase.now());db.setTransactionSuccessful();}finally{db.endTransaction();}inventory();}catch(Exception x){err("ราคาไม่ถูกต้อง");}}).setNegativeButton("ยกเลิก",null).show();}
 void count(String id,int old){EditText e=new EditText(this);e.setHint("จำนวนจริง");e.setInputType(2);new AlertDialog.Builder(this).setTitle("ตรวจนับ").setView(e).setPositiveButton("ยืนยัน",(d,w)->{try{int n=Integer.parseInt(e.getText().toString());if(n<0)throw new Exception();SQLiteDatabase db=helper.getWritableDatabase();db.beginTransaction();try{ContentValues v=new ContentValues();v.put("stock",n);v.put("updated_at",PosDatabase.now());db.update("products",v,"id=?",new String[]{id});ledger(db,id,n-old,old,n,"count_adjustment",null,PosDatabase.now());db.setTransactionSuccessful();}finally{db.endTransaction();}inventory();}catch(Exception x){err("จำนวนไม่ถูกต้อง");}}).setNegativeButton("ยกเลิก",null).show();}
 void ledger(SQLiteDatabase d,String pid,int delta,int before,int after,String reason,String ref,String now){ContentValues v=new ContentValues();v.put("id",PosDatabase.id());v.put("product_id",pid);v.put("delta",delta);v.put("before_qty",before);v.put("after_qty",after);v.put("reason",reason);v.put("reference_id",ref);v.put("created_at",now);d.insertOrThrow("inventory_ledger",null,v);}
 void barcode(){page("สร้างบาร์โค้ด");button("สร้างเลขให้สินค้าที่ยังไม่มี",()->{SQLiteDatabase d=helper.getWritableDatabase();d.beginTransaction();try(Cursor c=d.rawQuery("SELECT id FROM products WHERE barcode IS NULL ORDER BY created_at",null)){while(c.moveToNext()){long n=DatabaseUtils.longForQuery(d,"SELECT next_value FROM barcode_counter WHERE id=1",null);if(n>9999999)throw new IllegalStateException("barcode exhausted");ContentValues v=new ContentValues();v.put("barcode",Long.toString(n));v.put("updated_at",PosDatabase.now());d.update("products",v,"id=?",new String[]{c.getString(0)});ContentValues x=new ContentValues();x.put("next_value",n+1);d.update("barcode_counter",x,"id=1",null);}d.setTransactionSuccessful();}finally{d.endTransaction();}inventory();});}
 void sell(){page("ขายสินค้า");EditText code=input("สแกนบาร์โค้ด");EditText qty=input("จำนวน");EditText customer=input("ชื่อลูกค้า (ขายเชื่อ)");RadioGroup rg=new RadioGroup(this);RadioButton cash=new RadioButton(this),credit=new RadioButton(this);cash.setText("เงินสด");cash.setChecked(true);credit.setText("เงินเชื่อ");rg.addView(cash);rg.addView(credit);body.addView(rg);button("ยืนยันขาย",()->{try{String bc=code.getText().toString().trim();int q=Integer.parseInt(qty.getText().toString());boolean cr=credit.isChecked();if(bc.isEmpty()||q<=0)throw new Exception();SQLiteDatabase d=helper.getWritableDatabase();d.beginTransaction();try(Cursor c=d.rawQuery("SELECT id,name,price_sat,cost_sat,stock,track_stock FROM products WHERE barcode=? LIMIT 1",new String[]{bc})){if(!c.moveToFirst())throw new Exception();String pid=c.getString(0),name=c.getString(1);long price=c.getLong(2),cost=c.getLong(3);int stock=c.getInt(4);if(c.getInt(5)==1&&stock<q)throw new Exception();long total=Math.multiplyExact(price,q);String cid=null;if(cr){String cn=customer.getText().toString().trim();if(cn.isEmpty())throw new Exception();try(Cursor cc=d.rawQuery("SELECT id FROM customers WHERE name=? COLLATE NOCASE LIMIT 1",new String[]{cn})){if(cc.moveToFirst())cid=cc.getString(0);}if(cid==null){cid=PosDatabase.id();ContentValues cv=new ContentValues();cv.put("id",cid);cv.put("name",cn);cv.put("created_at",PosDatabase.now());d.insertOrThrow("customers",null,cv);}}String sid=PosDatabase.id(),now=PosDatabase.now(),receipt="R-"+UUID.randomUUID();ContentValues s=new ContentValues();s.put("id",sid);s.put("receipt_no",receipt);s.put("customer_id",cid);s.put("status","confirmed");s.put("kind",cr?"credit":"cash");s.put("subtotal_sat",total);s.put("paid_sat",cr?0:total);s.put("created_at",now);s.put("idempotency_key",PosDatabase.id());d.insertOrThrow("sales",null,s);ContentValues li=new ContentValues();li.put("id",PosDatabase.id());li.put("sale_id",sid);li.put("product_id",pid);li.put("name_snapshot",name);li.put("barcode_snapshot",bc);li.put("qty",q);li.put("unit_price_sat",price);li.put("unit_cost_sat",cost);li.put("line_total_sat",total);d.insertOrThrow("sale_items",null,li);if(!cr){ContentValues pay=new ContentValues();pay.put("id",PosDatabase.id());pay.put("sale_id",sid);pay.put("amount_sat",total);pay.put("method","cash");pay.put("created_at",now);d.insertOrThrow("payments",null,pay);}if(c.getInt(5)==1){ContentValues st=new ContentValues();st.put("stock",stock-q);st.put("updated_at",now);d.update("products",st,"id=?",new String[]{pid});ledger(d,pid,-q,stock,stock-q,"sale",sid,now);}if(cr){ContentValues debt=new ContentValues();debt.put("id",PosDatabase.id());debt.put("sale_id",sid);debt.put("customer_id",cid);debt.put("original_sat",total);debt.put("status","unpaid");debt.put("created_at",now);d.insertOrThrow("debts",null,debt);}audit(d,"sale",sid,"confirmed",receipt,now);d.setTransactionSuccessful();info("บันทึกบิลสำเร็จ "+receipt);}finally{d.endTransaction();}}catch(Exception x){err("ขายไม่สำเร็จ ตรวจบาร์โค้ด จำนวน และสต๊อก");}});}
 void debts(){page("บัญชีเชื่อ / ชำระหนี้");try(Cursor c=helper.getReadableDatabase().rawQuery("SELECT c.name,d.original_sat,d.paid_sat,d.status,d.id FROM debts d JOIN customers c ON c.id=d.customer_id ORDER BY d.created_at",null)){while(c.moveToNext()){String name=c.getString(0),id=c.getString(4);long rem=c.getLong(1)-c.getLong(2);button(name+" | ค้าง "+nf.format(rem/100.0)+" บาท | "+c.getString(3),()->receive(id,rem));}}}
 void receive(String id,long remain){EditText e=new EditText(this);e.setHint("รับชำระ (บาท)");e.setInputType(2);new AlertDialog.Builder(this).setTitle("ชำระหนี้").setView(e).setPositiveButton("บันทึก",(d,w)->{try{long a=Long.parseLong(e.getText().toString())*100;if(a<=0||a>remain)throw new Exception();SQLiteDatabase db=helper.getWritableDatabase();db.beginTransaction();try{long paid=DatabaseUtils.longForQuery(db,"SELECT paid_sat FROM debts WHERE id=?",new String[]{id});String now=PosDatabase.now();ContentValues p=new ContentValues();p.put("id",PosDatabase.id());p.put("debt_id",id);p.put("amount_sat",a);p.put("received_at",now);db.insertOrThrow("debt_payments",null,p);ContentValues u=new ContentValues();u.put("paid_sat",paid+a);u.put("status",paid+a==DatabaseUtils.longForQuery(db,"SELECT original_sat FROM debts WHERE id=?",new String[]{id})?"paid":"partial");if(paid+a==remain)u.put("paid_at",now);db.update("debts",u,"id=?",new String[]{id});db.setTransactionSuccessful();}finally{db.endTransaction();}debts();}catch(Exception x){err("ยอดชำระไม่ถูกต้อง");}}).setNegativeButton("ยกเลิก",null).show();}
 void history(){page("ประวัติการขาย");try(Cursor c=helper.getReadableDatabase().rawQuery("SELECT receipt_no,kind,subtotal_sat,created_at FROM sales ORDER BY created_at DESC LIMIT 500",null)){while(c.moveToNext())body.addView(label(c.getString(0)+" | "+c.getString(1)+" | "+nf.format(c.getLong(2)/100.0)+" บาท | "+c.getString(3),15));}}
 void reports(){page("รายงาน");SQLiteDatabase d=helper.getReadableDatabase();long sales=DatabaseUtils.longForQuery(d,"SELECT COALESCE(SUM(subtotal_sat),0) FROM sales WHERE status='confirmed'",null),cost=DatabaseUtils.longForQuery(d,"SELECT COALESCE(SUM(unit_cost_sat*qty),0) FROM sale_items",null),debt=DatabaseUtils.longForQuery(d,"SELECT COALESCE(SUM(original_sat-paid_sat),0) FROM debts WHERE status<>'paid'",null);body.addView(label("ยอดขายสะสม "+nf.format(sales/100.0)+" บาท",18));body.addView(label("ต้นทุนขาย "+nf.format(cost/100.0)+" บาท",18));body.addView(label("กำไรขั้นต้นโดยประมาณ "+nf.format((sales-cost)/100.0)+" บาท (ก่อนค่าใช้จ่าย)",18));body.addView(label("ลูกหนี้คงค้าง "+nf.format(debt/100.0)+" บาท",18));}
 void settings(){page("ตั้งค่า / ตรวจสอบ");button("สำรองฐานข้อมูล",()->{Intent i=new Intent(Intent.ACTION_CREATE_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("application/octet-stream");i.putExtra(Intent.EXTRA_TITLE,"mae-yai-on-pos-backup.db");startActivityForResult(i,7101);});button("กู้คืนฐานข้อมูลจากไฟล์",()->{new AlertDialog.Builder(this).setTitle("ยืนยันกู้คืน").setMessage("ข้อมูลปัจจุบันจะถูกแทนที่ด้วยข้อมูลในไฟล์สำรอง ควรสำรองข้อมูลปัจจุบันก่อนดำเนินการ").setNegativeButton("ยกเลิก",null).setPositiveButton("เลือกไฟล์",(d,w)->{Intent i=new Intent(Intent.ACTION_OPEN_DOCUMENT);i.addCategory(Intent.CATEGORY_OPENABLE);i.setType("*/*");startActivityForResult(i,7102);}).show();});button("ตรวจ integrity_check",()->{try(Cursor c=helper.getReadableDatabase().rawQuery("PRAGMA integrity_check",null)){c.moveToFirst();info(c.getString(0));}});button("ตรวจ foreign_key_check",()->{try(Cursor c=helper.getReadableDatabase().rawQuery("PRAGMA foreign_key_check",null)){info(c.moveToFirst()?"พบข้อผิดพลาด":"ไม่พบข้อผิดพลาด");}});body.addView(label("ฐานข้อมูลส่วนตัวของแอป; WAL, Foreign Keys และ Migration version 2 เปิดใช้งาน",14));}
 @Override protected void onActivityResult(int requestCode,int resultCode,Intent data){super.onActivityResult(requestCode,resultCode,data);if(resultCode!=RESULT_OK||data==null||data.getData()==null)return;Uri uri=data.getData();try{if(requestCode==7101){DatabaseBackup.exportTo(this,uri);info("สำรองฐานข้อมูลและตรวจสอบไฟล์สำเร็จ");}else if(requestCode==7102){DatabaseBackup.restoreFrom(this,uri);helper=PosDatabase.get(this);info("กู้คืนฐานข้อมูลสำเร็จและตรวจสอบแล้ว");home();}}catch(Exception e){helper=PosDatabase.get(this);err("สำรอง/กู้คืนไม่สำเร็จ: "+e.getMessage());}}
 void audit(SQLiteDatabase d,String entity,String id,String action,String detail,String now){ContentValues v=new ContentValues();v.put("id",PosDatabase.id());v.put("entity",entity);v.put("entity_id",id);v.put("action",action);v.put("detail",detail);v.put("created_at",now);d.insertOrThrow("audit_log",null,v);}
 void info(String s){new AlertDialog.Builder(this).setMessage(s).setPositiveButton("ตกลง",null).show();}void err(String s){new AlertDialog.Builder(this).setTitle("ทำรายการไม่สำเร็จ").setMessage(s).setPositiveButton("ตกลง",null).show();}
}
